Rewrite the following GNU C++17 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to rewrite:
<original_code>
#include <cstdio>
#include <cmath>
#include <iostream>
#include <algorithm>
using namespace std;
long long num11[20];
long long pow10[20];
int ans = 0;
void pre()
{
    pow10[0] = 1;
    for (int i = 1; i <= 17; i++)
    {
        pow10[i] = pow10[i - 1] * 10;
    }
    for (int i = 1; i <= 17; i++)
    {
        num11[i] = num11[i - 1] * 10 + 1;
        // cout << i << ' ' << num11[i] << '\n';
    }
}
int get_len(long long x)
{
    int res = 0;
    while (x)
    {
        res++;
        x /= 10;
    }
    return res;
}
void dfs(int pos, long long x, int cnt)
{

    if (ans != -1 && cnt >= ans)    return;
    if (x == 0 || pos == 0)
    {
        if (ans != -1)  ans = min(ans, cnt);
        else    ans = cnt;
        return;
    }
    if (x < 0)  x = -x;
    // printf("pos = %d, x = %lld, cnt = %d， pow10[pos] = %lld\n", pos, x, cnt, pow10[pos - 1]);
    long long t_x = x;
    int t_cnt = 0;
    while (t_x >= pow10[pos - 1])
    {
        t_x -= num11[pos];
        t_cnt += pos;
    }
    dfs(pos - 1, t_x, cnt + t_cnt);
    t_x = num11[pos + 1] - x;    t_cnt = 0;
    while (t_x >= pow10[pos - 1])
    {
        t_x -= num11[pos];
        t_cnt += pos;
    }
    dfs(pos - 1, t_x, cnt + pos + 1 + t_cnt);
}


void Solve()
{

    long long x;    scanf("%lld", &x);
    // while (cin >> x)    cout << get_len(x);
    ans = -1;
    dfs(get_len(x), x, 0);
    cout << ans << '\n';
}
int main()
{
    pre();
    // while (1)
    Solve();
    getchar(); getchar();
    return 0;
}
</original_code>
